def one_app_per_device(apps, schema_editor):
    """Calls moved to its own app (OCM Phone, decision 80). Every existing device is an OCM Messages device: it keeps SMS and
    loses Calls (its call history stays on the server). Codes list one app each."""
    Device = apps.get_model("devices", "Device")
    Invite = apps.get_model("devices", "EnrollmentInvite")
    for device in Device.objects.all():
        caps = dict(device.capabilities or {})
        if caps.get("sms", True):
            caps["calls"] = False
            device.app = "sms"
            device.capabilities = caps
            device.save(update_fields=["app", "capabilities"])
    for invite in Invite.objects.all():
        platforms = invite.platforms or ["sms"]
        first = "sms" if "sms" in platforms else platforms[0]
        if platforms != [first]:
            invite.platforms = [first]
            invite.save(update_fields=["platforms"])


